<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {businessApi,useBusinessStore} from '../stores/business';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import type {RoomSummary} from '@shared/mobile';import type {BusinessResult,NativeContext} from '@shared/business';import type {Target} from '@shared/labops-targets.js';import BusinessPlanCard from '../components/BusinessPlanCard.vue';import AsyncState from './AsyncState.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
const props=defineProps<{roomId?:string;action?:string}>(),emit=defineEmits<{navigate:[Target]}>(),business=useBusinessStore(),session=useSessionStore(),run=useRunStore(),rooms=ref<RoomSummary[]>([]),loading=ref(true),error=ref(''),query=ref(''),filter=ref('all'),date=ref(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())),workflow=ref<BusinessResult>();let generation=0;
const selected=computed(()=>rooms.value.find(r=>r.roomId===props.roomId)),list=computed(()=>rooms.value.filter(r=>(!query.value||r.roomName.toLowerCase().includes(query.value.toLowerCase())||r.location.includes(query.value))&&(filter.value==='all'||filter.value==='open'&&r.recordedDoorState==='open'||filter.value==='suspended'&&r.serviceState==='suspended'||filter.value==='inuse'&&(r.occupancy.value||0)>0||filter.value==='classes'&&r.scheduleState==='occupied')));
const labels:Record<string,string>={open:'登记开放',closed:'登记关闭',unknown:'未知',normal:'服务正常',suspended:'服务停用',occupied:'有课程占用',no_scheduled_class:'无已排课程',active:'档案开放',inactive:'档案停用',in_cabinet:'在钥匙柜',borrowed:'登记借用',handover:'登记位置待交接'};
async function refresh(){const epoch=++generation;try{const q=new URLSearchParams({date:date.value,...(props.roomId?{roomId:props.roomId}:{})}),result=await businessApi<{rooms:RoomSummary[]}>('proxy/room-summaries?'+q);if(epoch===generation){rooms.value=result.rooms;error.value='';}}catch(e){if(epoch===generation)error.value=(e as Error).message;}finally{loading.value=false;}}
async function openWorkflow(view:string){if(run.inputLocked)return;try{const context=await businessApi<NativeContext>('proxy/context');session.startDraft();workflow.value={summary:'本人从实验室详情进入正式办理流程',view:view as BusinessResult['view'],planId:null,context,candidates:[],date:date.value,initialRoomId:props.roomId,scopeKey:business.scopeKey,source:'主系统授权业务接口',queriedAt:new Date().toISOString(),workbenchUrl:'/operations.html?bridge=1'};}catch(e){error.value=(e as Error).message;}}
async function enter(){workflow.value=undefined;await refresh();if(props.action)await openWorkflow(props.action);}
onMounted(enter);watch(()=>[props.roomId,props.action],enter);watch(date,refresh);useVisibleRefresh(refresh,()=>!workflow.value);
</script>
<template><AsyncState :loading="loading" :error="error" @retry="refresh"><template v-if="!roomId"><div class="mobile-search"><label class="sr-only" for="room-search">搜索实验室</label><input id="room-search" v-model="query" type="search" placeholder="搜索名称或位置"><label><span class="sr-only">房间筛选</span><select v-model="filter"><option value="all">全部</option><option value="open">登记开放</option><option value="suspended">服务停用</option><option value="inuse">有有效签到记录</option><option value="classes">有课程占用</option></select></label></div><p v-if="!list.length" class="mobile-state">没有符合条件的实验室。</p><button v-for="r in list" :key="r.roomId" class="mobile-room mobile-row" @click="emit('navigate',{view:'room',roomId:r.roomId})"><div><b>{{r.roomName}}</b><span>{{r.kind==='lab'?'上机实验室':'开放实验室'}} · {{r.location}}</span></div><p>{{labels[r.recordedDoorState]}} · {{labels[r.serviceState]}}</p><p>有效签到记录 {{r.occupancy.value===null?'未知':r.occupancy.value}} 条 · {{labels[r.scheduleState]}}</p><small>档案：{{labels[r.registryStatus]||r.registryStatus}} · {{r.occupancy.date}}</small></button></template><template v-else-if="selected"><template v-if="!workflow"><div class="mobile-greeting"><h2>{{selected.roomName}}</h2><p>{{selected.location}} · 容量 {{selected.capacity??'未知'}}</p></div><section class="mobile-section"><h3>当前登记与服务</h3><dl class="mobile-facts"><dt>房间档案</dt><dd>{{labels[selected.registryStatus]||selected.registryStatus}}</dd><dt>人员登记开放</dt><dd>{{labels[selected.recordedDoorState]}}<small>{{selected.doorRecordedAt||'登记时间未知'}}</small></dd><dt>服务状态</dt><dd>{{labels[selected.serviceState]}}</dd><dt>教学占用</dt><dd>{{labels[selected.scheduleState]}}</dd><dt>有效签到记录</dt><dd>{{selected.occupancy.value??'未知'}} 条 · {{selected.occupancy.quality==='valid'?'统计可用':selected.occupancy.quality==='partial'?'存在待核实记录':'不可用'}}</dd></dl><p class="mobile-formal">{{selected.doorNote}}。{{selected.occupancy.note}}</p><div v-for="c in selected.closures" :key="c.id" class="mobile-warning">{{c.startDate}} 至 {{c.endDate}} · {{c.reason}}</div></section><section class="mobile-section"><h3>指定日期课程</h3><label>上海日期<input v-model="date" type="date"></label><p v-for="t in selected.schedule" :key="t.id">{{t.periodKey}} · {{t.courseName}} · {{(t.classNames||[t.className]).join('、')}}</p><p v-if="!selected.schedule.length">{{selected.scheduleState==='unknown'?'校历或课表不完整，课程情况未知。':'该日没有已排课程。'}}</p></section><section class="mobile-section"><h3>钥匙登记</h3><p>{{labels[selected.key.state]}} · {{selected.key.location||'位置未知'}} · {{selected.key.holder||'未登记借用人'}}</p><p>{{selected.key.note}} · {{selected.key.recordedAt||'登记时间未知'}}</p></section><section class="mobile-section"><h3>可见的相关业务</h3><p v-for="i in selected.related.issues" :key="i.id">工单 {{i.id}} · {{i.status}} · {{i.description}}</p><p v-for="s in selected.related.shifts" :key="s.id">班次 {{s.id}} · {{s.periodKey}} · {{s.userId}}</p><p v-for="h in selected.related.handovers" :key="h.id">交接 {{h.id}} · {{h.status}}</p><div v-for="i in selected.related.inspections" :key="i.id"><p>检查 {{i.id}} · {{i.date}}</p><p v-for="(c,index) in i.checklist" :key="index">{{c.label}} · {{c.state==='done'?'已确认':c.state==='abnormal'?'异常':'未确认'}}</p><p v-if="i.note">{{i.note}}</p></div><p v-for="i in selected.related.items" :key="i.id">遗留事项 {{i.id}} · {{i.state}} · {{i.description}} · 截止 {{i.deadline||'未设置'}}</p><p v-if="!selected.related.issues.length&&!selected.related.shifts.length&&!selected.related.handovers.length&&!selected.related.inspections.length&&!selected.related.items.length">当前范围没有相关记录。</p></section><section class="mobile-section"><h3>进入正式办理</h3><p>填写事实、预览方案、本人确认后提交到主系统。</p><div class="mobile-actions"><button :disabled="run.inputLocked" @click="emit('navigate',{view:'room',roomId,action:'issues'})">报修与工单</button><button :disabled="run.inputLocked" @click="emit('navigate',{view:'room',roomId,action:'duty'})">检查与交接</button><button v-if="business.profile?.identity==='admin'" :disabled="run.inputLocked" @click="emit('navigate',{view:'room',roomId,action:'schedule'})">指定日期调课</button><button v-if="business.profile?.identity==='admin'" :disabled="run.inputLocked" @click="emit('navigate',{view:'room',roomId,action:'closures'})">停用与撤销</button><button @click="emit('navigate',{view:'evidence',roomId:selected.roomId})">证据与资料</button></div></section><p class="mobile-source">查询 {{selected.queriedAt}} · 版本 {{selected.sourceRevision.slice(0,12)}}</p></template><template v-else><button class="mobile-back-inline" @click="emit('navigate',{view:'room',roomId})">返回房间详情</button><BusinessPlanCard :key="roomId+':'+workflow.view" :result="workflow" :card-id="'mobile-room:'+roomId+':'+workflow.view" :readonly="run.inputLocked"/></template></template></AsyncState></template>
